(()=>{
const E=s=>typeof esc==='function'?esc(s):String(s??'');
function docs(){try{return Array.isArray(documents)?documents:[]}catch{return[]}}
function invoiceByNumber(num){return docs().find(d=>d.document_type==='rechnung'&&String(d.document_number||'')===String(num))}
function openNewReport(inv){if(typeof window.openBautagesbericht!=='function'){window.showView?.('bautage');setTimeout(()=>window.openBautagesbericht?.(),150);return}window.openBautagesbericht();setTimeout(()=>{const p=inv?.payload||{},c=document.getElementById('btCustomer'),s=document.getElementById('btSite');if(c&&p.customer_id)c.value=String(p.customer_id);if(s&&!s.value)s.value=p.subject||''},50)}
window.hpOpenBundle=function(id){const inv=docs().find(d=>String(d.id)===String(id));if(!inv)return alert('Rechnung konnte nicht geladen werden.');const reports=docs().filter(d=>d.document_type==='bautagesbericht');if(!reports.length){openNewReport(inv);return}window.closeModal?.();window.showView?.('bautage')};
function decorateCards(){document.querySelectorAll('#docList .item,#docList .card').forEach(card=>{const m=(card.textContent||'').match(/Rechnung\s+(RE-[0-9-]+)/i);if(!m)return;const num=m[1],actions=card.querySelector('.actions')||card;[...actions.querySelectorAll('button')].filter(b=>/PDF\s*\/\s*Drucken|Drucken\s*\/\s*PDF/i.test(b.textContent||'')).forEach(b=>b.remove());let bs=[...card.querySelectorAll('button')].filter(b=>/Bautagesberichte/i.test(b.textContent||''));let b=bs[0];bs.slice(1).forEach(x=>x.remove());if(!b){const send=[...actions.querySelectorAll('button')].find(x=>/PDF senden/i.test(x.textContent||''));b=document.createElement('button');b.type='button';b.className='btn secondary';b.textContent='📎 Bautagesberichte';if(send)send.insertAdjacentElement('beforebegin',b);else actions.appendChild(b)}b.dataset.hpBundle=num;b.onclick=e=>{e.preventDefault();e.stopPropagation();const inv=invoiceByNumber(num);if(!inv)return alert('Rechnung wird noch geladen. Bitte kurz erneut tippen.');window.hpOpenBundle(String(inv.id))}})}
document.addEventListener('click',e=>{const b=e.target.closest?.('[data-hp-bundle]');if(!b)return;e.preventDefault();e.stopPropagation();const inv=invoiceByNumber(b.dataset.hpBundle);if(!inv)return alert('Rechnung wird noch geladen. Bitte kurz erneut tippen.');window.hpOpenBundle(String(inv.id))},true);
setTimeout(decorateCards,100);setTimeout(decorateCards,600);setInterval(decorateCards,1800);new MutationObserver(()=>setTimeout(decorateCards,0)).observe(document.documentElement,{subtree:true,childList:true});
})();